// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    W_WALLET c;
    address logAddr;

    function setUp() public {
        logAddr = address(new Log());
        c = new W_WALLET(logAddr);
    }

    function testFuzz_property(uint256 deposit, uint256 amount, uint256 unlockTime) public {
        vm.assume(deposit <= VALUE_CAP);
        // Admissible domain: non-zero deposit and amount, no overflow, and enough balance.
        deposit = bound(deposit, 1, 1 ether);
        amount = bound(amount, 1, deposit);
        unlockTime = bound(unlockTime, 0, block.timestamp);

        // Set up the Log counterparty that C calls out to.
        vm.prank(address(c));
        (bool setLogOk, ) = logAddr.call(
            abi.encodeWithSignature("fallback()")
        );
        // The needed setup is actually setting C.LogFile; do it via the test contract
        // because C has no public setter. Use a low-level call to C's fallback? No.
        // Instead, we use vm.store? Not allowed. Re-read the requirements:
        // Set LogFile FIRST with fallback(...) passing a Log deployed in the test.
        // C's fallback calls Put(0), which touches LogFile. But LogFile is address(0)?
        // Actually the constructor sets LogFile = Log(log).
        // So setup is already done in setUp (new C(address(new Log()))).
        // The note about fallback(...) first is for cases where LogFile starts unset.
        // Here it is set in constructor, so no extra setup needed.

        // Give the test contract ether and deposit into C.
        vm.deal(address(this), deposit);
        c.Put{value: deposit}(unlockTime);

        // Warp past unlock time so Collect can succeed.
        vm.warp(block.timestamp + 1);

        // Now call Collect. On reference, the lock is unlocked, so it succeeds.
        // On mutant, the lock is inverted, so require(locked_) fails and it reverts.
        bool ok; try c.Collect(amount) { ok = true; } catch { ok = false; }

        // The general rule: for an admissible deposit and collect amount, Collect must succeed.
        assertTrue(ok);
    }
}
